create table if not exists public.business_digital_twins (id uuid primary key default gen_random_uuid(), workspace_id uuid not null, business_id uuid, profile jsonb not null default '{}'::jsonb, products jsonb not null default '[]'::jsonb, services jsonb not null default '[]'::jsonb, brand_voice jsonb not null default '{}'::jsonb, target_audience jsonb not null default '{}'::jsonb, channel_summary jsonb not null default '{}'::jsonb, customer_journey jsonb not null default '{}'::jsonb, competitor_summary jsonb not null default '{}'::jsonb, confidence numeric(5,4) not null default 0, evidence_count integer not null default 0, version integer not null default 1, last_refreshed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(workspace_id,business_id)); alter table public.business_digital_twins enable row level security; create policy "members_read_business_digital_twins" on public.business_digital_twins for select to authenticated using (public.is_workspace_member(auth.uid(), workspace_id));;
